const input = $input.first().json;
const body = input.body && typeof input.body === 'object' ? input.body : input;

const value = (...keys) => {
  for (const key of keys) {
    const candidate = body[key];
    if (candidate !== undefined && candidate !== null && String(candidate).trim() !== '') {
      return typeof candidate === 'string' ? candidate.trim() : candidate;
    }
  }
  return null;
};

const email = value('email', 'email_address', 'emailAddress');
const phone = value('phone', 'phone_number', 'phoneNumber');
const service = value('service', 'service_interest', 'serviceInterest');
const message = String(value('message', 'notes', 'details') || '').toLowerCase();
const timeframe = String(value('timeframe', 'timeline', 'when') || '').toLowerCase();

let score = 0;
const reasons = [];

if (email || phone) {
  score += 2;
  reasons.push('reachable contact');
}

if (service) {
  score += 2;
  reasons.push('service identified');
}

if (/urgent|emergency|today|same day|asap/.test(message + ' ' + timeframe)) {
  score += 3;
  reasons.push('high-intent timeframe');
}

if (/quote|estimate|book|appointment|schedule|consult/.test(message)) {
  score += 2;
  reasons.push('commercial intent');
}

const priority = score >= 6 ? 'high' : score >= 3 ? 'medium' : 'low';
const route =
  priority === 'high'
    ? 'priority-intake'
    : priority === 'medium'
      ? 'standard-intake'
      : 'nurture';

return [{
  json: {
    lead: {
      fullName: value('full_name', 'fullName', 'name'),
      email,
      phone,
      service,
      message: value('message', 'notes', 'details'),
    },
    routing: {
      score,
      priority,
      route,
      reasons,
    },
    meta: {
      evaluatedAt: new Date().toISOString(),
    },
  },
}];
